class Solution {
  public int minimumCost(int m, int n, int[] horizontalCut, int[] verticalCut) {
    int[] h = horizontalCut.clone(), v = verticalCut.clone();
    Arrays.sort(h);
    Arrays.sort(v);
    int i = h.length - 1, j = v.length - 1, horizontalPieces = 1, verticalPieces = 1;
    long total = 0;
    // always take the most expensive remaining cut: it should cross as few pieces as possible
    while (i >= 0 || j >= 0) {
      if (j < 0 || (i >= 0 && h[i] >= v[j])) {
        total += (long) h[i--] * verticalPieces;
        horizontalPieces++;
      } else {
        total += (long) v[j--] * horizontalPieces;
        verticalPieces++;
      }
    }
    return (int) total;
  }
}
